client_script.script:

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
  if (isLoading || isTemplate) {
    return;
  }

  var priority = parseInt(newValue);

  // Validate priority is between 1 and 5
  if (isNaN(priority) || priority < 1 || priority > 5) {
    g_form.setMandatory('priority', true);
    g_form.showErrorBox('priority', 'Priority must be between 1 and 5');
    g_form.clearValue('priority');
    return false;
  }

  // Clear error if valid
  g_form.clearErrorBox('priority');
  g_form.setMandatory('priority', true);
}
